targets.expr:
sum by (endpointslice) (
  kube_endpointslice_endpoints{
    namespace="$app_namespace",
    endpointslice=~"$endpoint_regex.*",
    ready="true"
  }
)
or
sum by (endpoint) (
  kube_endpoint_address{
    namespace="$app_namespace",
    endpoint=~"$endpoint_regex",
    ready="true"
  }
)
or
sum by (endpoint) (
  kube_endpoint_address_available{
    namespace="$app_namespace",
    endpoint=~"$endpoint_regex"
  }
)
